import{_ as a,c as e,o as r,ae as o}from"./chunks/framework.BvcDoAct.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"scripts/output/1_translated.md","filePath":"scripts/output/1_translated.md"}'),s={name:"scripts/output/1_translated.md"};function i(n,t,p,l,c,_){return r(),e("div",null,[...t[0]||(t[0]=[o('<h2 id="title-vitepress" tabindex="-1">title: VitePress <a class="header-anchor" href="#title-vitepress" aria-label="Permalink to &quot;title: VitePress&quot;">​</a></h2><h2 id="在持续进化的岁月根底-刻着各自的信念——" tabindex="-1">在持续进化的岁月根底，刻着各自的信念—— <a class="header-anchor" href="#在持续进化的岁月根底-刻着各自的信念——" aria-label="Permalink to &quot;在持续进化的岁月根底，刻着各自的信念——&quot;">​</a></h2><h2 id="一路追随-be-first-的《rockin-on-japan》-献上从过去通往未来的长传式访谈" tabindex="-1">一路追随 BE:FIRST 的《rockin&#39;on JAPAN》，献上从过去通往未来的长传式访谈 <a class="header-anchor" href="#一路追随-be-first-的《rockin-on-japan》-献上从过去通往未来的长传式访谈" aria-label="Permalink to &quot;一路追随 BE:FIRST 的《rockin&#39;on JAPAN》，献上从过去通往未来的长传式访谈&quot;">​</a></h2><p>2021 年，从选秀企划《THE FIRST》诞生的 BE:FIRST，于 11 月 3 日迎来主流出道 4 周年。就在此前的 10 月 29 日，他们发行了组合首张精选专辑《BE:ST》。4 年就推出精选——放在一般艺人身上，或许会让人觉得稍微早了点；但当你看着曲目表上排开的 30 多首歌曲，就会明白。刻在这里的每一首风格丰富、面向多元的作品，都是他们高密度日常的足迹，也是进化的证据。</p><p>4 年前，在事务所社长兼制作人 SKY-HI 的引领下起步的 BE:FIRST，如今正带着健康的自由与旺盛的好奇心，靠自己的双脚一阶一阶向上奔跑。从巨蛋巡演到世界巡演，再到体育场公演，现场规模不断扩张，这就是最直接的证明。更重要的是，这背后还有一段清晰的轨迹：成员们主动深度参与歌曲制作，把「当下真正需要的声音」亲手拉到眼前并做成作品。首张专辑《BE:1》主打曲《Scream》里有一句歌词——「去证明什么才是最强」——而正如这句宣言，他们一路走到今天，始终在不断刷新并证明属于自己的「最强」。</p><p>在《BE:ST》这个时间点制作 BE:FIRST 特集时，我们想到的是：想把这段耀眼历史背后，成员每个人当时到底在想什么，一一解开。</p><p>作为最强进化团体 BE:FIRST 继续走下去，他们究竟改变了什么，又是如何守住那些没有改变的部分——其实，《rockin&#39;on JAPAN》早在《BE:1》发行后的 2022 年秋天起，就用了约半年时间，完成了成员个人专访连载。这次别册特集中，我们一边摘取他们当年各自说过的话，一边尝试做一次再次触及他们根底信念的访谈（另外，各采访页也重新刊载了 3 年前文章中的旧照，也请留意他们的变化）。</p><p>为什么 BE:FIRST 是 BE:FIRST？为什么他们能持续证明「最强」？</p><p>我想，这次特集已经成为一组能够触到其真髓的、独一无二的内容。 <br><br></p><p>（安田季那子）</p><p>采访＝小川智宏　摄影＝大野隼男</p><hr>',12)])])}const S=a(s,[["render",i]]);export{h as __pageData,S as default};
